/* Illustrated island map: painted terrain and geographic hit areas. */
let deploySelected=null;
function mapSVG({current=null,selected=null,closed=GRAIL_WORLD.restricted(DATA),soon=[],locations=[],locked=false,start=false}={}){
 const cells=DATA.regions.map(r=>{const id=r.id,a=MAP_AREAS[id],isClosed=r.restricted||closed.includes(id),isCurrent=current===id,isSelected=selected===id,isWarning=soon.includes(id),status=isClosed?(r.restricted?'기본 폐쇄':'폐쇄'):isCurrent?'현재 위치':isSelected?'선택됨':isWarning?'폐쇄 예정':'선택 가능';const attrs=!isClosed&&!locked?`role="button" tabindex="0" data-map-pick="${id}" aria-label="${r.name} · ${status}" aria-pressed="${isSelected}"`:`role="img" aria-label="${r.name} · ${status}"`;const label=mapLabelPlate(a.x,a.y,Math.max(64,r.name.length*18+22),id,r.name,status,{selected:isSelected,current:isCurrent,closed:isClosed,warning:isWarning,locked});return `<g class="district district-${id} ${isClosed?'is-closed':''} ${isCurrent?'is-current':''} ${isSelected?'is-selected':''} ${isWarning?'is-warning':''}" ${attrs}><path class="district-land" d="${a.shape}"/>${label}</g>`;}).join('');
 const materialMarkers=locations.filter(id=>MAP_AREAS[id]).map(id=>{const a=MAP_AREAS[id];return `<g class="material-location-marker" transform="translate(${a.x} ${a.y-93})"><circle r="10"/><path d="m-4 0 3 3 6-7"/></g>`;}).join('');
 const from=MAP_AREAS[current],to=MAP_AREAS[selected];
 return `<div class="map-surface"><svg class="world-map illustrated-world-map" viewBox="0 0 1000 680" role="group" aria-label="22개 지역 지도"><defs><linearGradient id="map-ocean" x2="0" y2="1"><stop stop-color="#315f72"/><stop offset="1" stop-color="#224b62"/></linearGradient><linearGradient id="island-grass" x2=".4" y2="1"><stop stop-color="#9bac83"/><stop offset=".55" stop-color="#86a47a"/><stop offset="1" stop-color="#769b78"/></linearGradient><clipPath id="island-clip"><path d="${MAP_COAST_PATH}"/></clipPath><pattern id="sea-ripples" width="92" height="62" patternUnits="userSpaceOnUse"><path d="M10 22q9-5 18 0t18 0m12 33q9-5 18 0" fill="none" stroke="#9fc9c6" stroke-width="1" opacity=".12"/></pattern><pattern id="closed-hatch" width="14" height="14" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="14" height="14" fill="#773d3b" fill-opacity=".15"/><path d="M0 0v14" stroke="#b7776a" stroke-opacity=".7" stroke-width="2"/></pattern><marker id="route-arrow" markerWidth="9" markerHeight="9" refX="7" refY="4.5" orient="auto"><path d="M0 0 9 4.5 0 9Z" fill="#fff0b0"/></marker></defs><rect width="1000" height="680" rx="12" fill="url(#map-ocean)"/><rect width="1000" height="680" fill="url(#sea-ripples)"/><g class="ocean-depth-lines" aria-hidden="true"><path d="M25 230Q12 133 150 80T330 20M15 490q70 151 280 133t300 30 380-20M840 165q160 50 145 170"/></g>${worldMapTerrain()}<g class="map-title" aria-hidden="true"><text x="29" y="34">루미아 섬</text><text x="30" y="51" class="map-title-caption">LUMIA ISLAND · 22 DISTRICTS</text></g><g class="districts">${cells}</g>${current&&from?`<path class="map-current-outline ${closed.includes(current)||soon.includes(current)?'map-current-danger':''}" d="${from.shape}" aria-hidden="true"/>`:''}${selected&&to&&!closed.includes(selected)?`<g class="map-selection-outline" data-outline-region="${selected}" aria-hidden="true"><path class="outline-halo" d="${to.shape}"/><path class="outline-color" d="${to.shape}"/></g>`:''}${materialMarkers}${from&&to&&current!==selected&&!closed.includes(selected)?`<path class="map-route" d="M${from.x} ${from.y-22}Q${(from.x+to.x)/2} ${(from.y+to.y)/2-100} ${to.x} ${to.y-25}" marker-end="url(#route-arrow)" aria-hidden="true"/>`:''}<g class="map-compass" transform="translate(955 52)" aria-hidden="true"><path d="M0-16-7 8 0 4 7 8Z"/><text y="-22">N</text></g><text class="map-sea-label" x="880" y="658">LUMIA COAST</text></svg><details class="map-region-index"><summary>지역 목록으로 선택 · 22개</summary><div class="region-index-grid">${DATA.regions.map(r=>{const blocked=r.restricted||closed.includes(r.id);return `<button type="button" data-map-pick="${r.id}" ${blocked||locked?'disabled':''} aria-pressed="${selected===r.id}" class="${current===r.id?'current':''} ${soon.includes(r.id)?'soon':''}"><small>${String(r.id).padStart(2,'0')}</small>${r.name}${blocked?' ×':''}</button>`;}).join('')}</div></details></div>`;
}
function mapLegend(start=false){return `<div class="world-legend">${!start?'<span><i class="legend-current"></i>현재 위치</span>':''}<span><i class="legend-selected"></i>${start?'선택 지역':'목적지'}</span><span><i class="legend-warning"></i>폐쇄 예정</span><span><i class="legend-closed"></i>폐쇄</span></div>`;}
function regionInfo(id,{start=false,locked=false,seal=false}={}){
 if(!id)return `<aside class="map-info"><span class="map-info-eyebrow">${start?'FIRST DESTINATION':'DESTINATION'}</span><h3>지역을 선택하세요</h3><p>일반 지역 21개 · 기본 폐쇄 연구소 1개.<br>지역을 누르면 원작 기준 고정 배치를 확인할 수 있어요.</p><div class="map-empty-symbol">${icon('pin')}</div><p>${start?'연구소를 제외한 21개 지역에서 첫 지역을 직접 정하세요. 같은 지역을 함께 선택할 수 있어요.':'목적지를 선택한 뒤 이동 버튼을 눌러야 이동합니다.'}</p></aside>`;
 const r=DATA.regions.find(r=>r.id===id),closed=r.restricted||(!start&&closedRegions().includes(id)),same=!start&&state.region===id,soon=!start&&(state.warningDemo||nextClosure()-elapsed()<=30)&&closurePair().includes(id),wait=!start&&remaining(state.moveUntil)>0;
 const action=start?'data-front="deploy-confirm"':`data-action="${seal?'seal-travel':'travel'}" data-id="${id}"`;
 return `<aside class="map-info"><span class="map-info-eyebrow">SECTOR ${String(id).padStart(2,'0')} / ${MAP_AREAS[id].type}</span><h3>${r.name}</h3><span class="destination-status ${closed||soon?'danger':''}">${start?(locked?'시작 지역 확정':'선택한 시작 지역'):closed?'폐쇄 · 이동 불가':same?'현재 위치':soon?'폐쇄 예정 지역':'선택한 목적지'}</span><h4>발견 가능한 아이템 <small>${r.loot.length}종</small></h4><div class="map-loot">${r.loot.map(l=>`<span title="초기 ${l.stockDiscoveries}묶음 · 발견당 ${l.quantityPerDiscovery}개">${esc(ITEMS[l.itemId].name)} <small>×${l.stockDiscoveries}${l.quantityPerDiscovery>1?'묶음':''}</small></span>`).join('')}</div><p class="map-stock-note">고정 초기 배치입니다. 묶음 아이템은 수량에 커서를 올리면 발견당 개수를 볼 수 있어요. 무작위 배치와 남은 재고는 공개하지 않습니다.</p>${soon?'<p class="map-danger-note">곧 폐쇄됩니다. 이동 후 안내 시간을 확인하세요.</p>':''}<div class="map-cost"><span>${start?'시작 배치':seal?'령주 도주':'일반 이동'}</span><strong>${start?'STA 소모 없음':seal?'령주 1획 · STA 5':'STA '+Math.max(0,5-(window.roomConnected?onlineEffects('move_stamina_reduction'):0))}</strong></div><button class="map-confirm" ${action} ${locked||closed||same?'disabled':''}>${locked?'다른 참가자를 기다리는 중':start?'이 지역에서 시작':closed?'폐쇄된 지역':same?'현재 있는 지역':seal?'령주로 '+r.name+' 도주':r.name+'(으)로 이동'}${!locked&&!closed&&!same?icon('arrow'):''}</button>${!start?`<p class="map-confirm-note">${wait&&!seal?'이동 대기 중 · 대기 후 이동할 수 있어요.':'이동 후 일반 이동 대기 3초'}</p>`:''}</aside>`;
}
function deploymentMarkup(){const locked=!!(roomKey&&roomView?.ownRegion);if(locked)deploySelected=roomView.ownRegion;return `<section class="lobby-page deployment-page"><div class="page-heading"><div><span class="eyebrow">CHOOSE YOUR FIRST DESTINATION</span><h1>어디서 시작할까요?</h1><p>${roomKey?'모든 참가자가 선택을 마치면 경기가 시작됩니다.':'UI 연습을 시작할 지역을 골라 주세요.'} 같은 지역을 선택할 수 있어요.</p></div>${button(roomKey?'leave':'home',roomKey?'방 나가기':'로비로')}</div><div class="deployment-status"><span>${icon('pin')} ${locked?'시작 지역 확정':'지도에서 시작 지역 선택'}</span><span>${roomKey?roomView.selectedCount+' / '+roomView.roster.length+'명 선택 완료':'선택 전에는 경기 시간이 흐르지 않습니다.'}</span></div><div class="world-map-layout">${mapSVG({selected:deploySelected,start:true,locked})}${regionInfo(deploySelected,{start:true,locked})}</div>${mapLegend(true)}<p class="map-bottom-note">다른 참가자의 시작 위치는 공개하지 않습니다. 지도 배치는 지형을 나타내며, 전투에서는 모든 열린 지역 사이를 이동할 수 있습니다.</p></section>`;}
mapDialog=function(focusItem=null,refresh=false){if(modalType==='map'&&!focusItem&&!refresh){closeModal();return;}if(!refresh)state.mapDestination=null;state.mapFocus=focusItem;state.mapSignature=mapStateSignature();const item=focusItem&&ITEMS[focusItem],locations=item?.loot?.regionIds||[],soon=(state.warningDemo||nextClosure()-elapsed()<=30)?closurePair():[];showModal('이동 지도',`<div class="world-map-heading"><span>현재 위치 <strong>${region().name}</strong></span><span id="map-move-wait"></span><kbd>E 닫기</kbd></div>${item?`<div class="map-focus">${icon(itemIcon(item))}${esc(item.name)} 발견 지역 · 지도에 점으로 표시</div>`:''}<div class="world-map-layout">${mapSVG({current:state.region,selected:state.mapDestination,closed:closedRegions(),soon,locations})}${regionInfo(state.mapDestination)}</div>${mapLegend()}<p class="map-bottom-note">열린 지역은 모두 직접 이동할 수 있습니다. 지역 선택만으로 이동하거나 STA를 소비하지 않습니다.</p>`,'map');updateHud();};
function sealWorldMap(){state.mapDestination=null;showModal('령주 도주 · 목적지 선택',`<div class="world-map-heading"><span>현재 위치 <strong>${region().name}</strong></span><span>이동 대기를 무시합니다 · 령주 1획</span></div><div class="world-map-layout">${mapSVG({current:state.region,closed:closedRegions()})}${regionInfo(null,{seal:true})}</div>${mapLegend()}`,'map-seal');}
function selectMapRegion(id){if(!DATA.regions.some(r=>r.id===id&&!r.restricted))return;if(window.frontScreen&&front==='deployment'){if(roomKey&&roomView?.ownRegion)return;deploySelected=id;frontRender();return;}if(!['map','map-seal'].includes(modalType))return;if(closedRegions().includes(id))return;state.mapDestination=id;if(modalType==='map'){mapDialog(state.mapFocus,true);}else{showModal('령주 도주 · 목적지 선택',`<div class="world-map-heading"><span>현재 위치 <strong>${region().name}</strong></span><span>령주 1획 · 이동 대기 무시</span></div><div class="world-map-layout">${mapSVG({current:state.region,selected:id,closed:closedRegions()})}${regionInfo(id,{seal:true})}</div>${mapLegend()}`,'map-seal');}}
document.addEventListener('click',e=>{const region=e.target.closest('[data-map-pick]');if(region){e.preventDefault();e.stopImmediatePropagation();selectMapRegion(Number(region.dataset.mapPick));return;}if(e.target.closest('[data-action="seal-map"]')){e.preventDefault();e.stopImmediatePropagation();sealWorldMap();}},true);
document.addEventListener('keydown',e=>{const region=e.target.closest('[data-map-pick]');if(region&&['Enter',' '].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();selectMapRegion(Number(region.dataset.mapPick));}},true);
